        if kw is not None:
            return self._get_first_name(kw_idx, keywords=True)","new_text":"        kw_idx, kw = self.token_next_by(m=(T.Keyword, 'AS'))
        if kw is not None:
            return self._get_first_name(kw_idx + 1, keywords=True)"}},{"id":"cli_15_2","name":"run","arguments":{"command":"python -c "import sqlparse; s=sqlparse.parse('SELECT sql_identifier AS view')[0]; ident = s.tokens[2]; print(repr(ident.get_alias()), repr(ident.get_real_name()), repr(ident.get_name()))""}}]}

